CREATE SCHEMA agent;
CREATE SCHEMA collaboration;
CREATE SCHEMA artifact;
CREATE SCHEMA resource;
CREATE TABLE agent.agent_dialogue_entries(entry_id uuid,tenant_id uuid,owner_id uuid,dialogue_id uuid,author_agent_id uuid,artifact_id uuid,artifact_version_id uuid,kind text);
CREATE TABLE agent.dialogue_publications(entry_id uuid,tenant_id uuid,owner_id uuid,dialogue_id uuid,agent_id uuid,execution_home text,source_kind text,source_intent_id uuid,source_conversation_id uuid,source_run_id uuid,source_tool_invocation_id uuid,device_subject_kind text);
CREATE TABLE agent.device_admissions(tenant_id uuid,owner_id uuid,agent_id uuid,dialogue_id uuid,intent_id uuid,conversation_id uuid,run_id uuid,admitted_snapshot_hash bytea,admitted_at_ms bigint);
CREATE TABLE agent.device_grant_heads(intent_id uuid,admitted_revision bigint);
CREATE TABLE agent.device_grant_versions(intent_id uuid,revision bigint,signed_grant_hash bytea);
CREATE TABLE collaboration.work_item_device_admitted_custody(work_item_id uuid,goal_revision bigint,control_revision bigint,assignment_epoch bigint,run_id uuid,conversation_id uuid,admitted_snapshot_hash bytea,signed_grant_hash bytea,admitted_at_ms bigint);
CREATE TABLE collaboration.work_item_execution_reservations(work_item_id uuid,goal_revision bigint,control_revision bigint,assignment_epoch bigint,run_id uuid,conversation_id uuid,tenant_id uuid,owner_id uuid,executing_agent_id uuid);
CREATE TABLE collaboration.work_items(work_item_id uuid,tenant_id uuid,owner_id uuid,source_intent_id uuid,erasure_job_id uuid);
CREATE TABLE agent.dialogue_tool_publication_groups(invocation_id uuid,tenant_id uuid,source_intent_id uuid,source_run_id uuid,execution_home text,device_snapshot_hash bytea,device_grant_proof_hash bytea,device_subject_kind text,device_export_commitment bytea,device_resource_commitment bytea,tool_ref text,device_receipt_content_id uuid);
CREATE TABLE agent.owned_agents(agent_id uuid,dialogue_id uuid,space_id uuid,status text);
CREATE TABLE agent.owner_spaces(space_id uuid,tenant_id uuid,owner_id uuid,product text);
CREATE TABLE artifact.artifacts(artifact_id uuid,tenant_id uuid,conversation_id uuid,workspace_id uuid,activity_id uuid,created_by_run_id uuid,origin smallint,kind smallint,lifecycle smallint,current_version bigint,title text,title_erasure_job_id uuid,created_at_ms bigint,updated_at_ms bigint);
CREATE TABLE artifact.artifact_versions(artifact_version_id uuid,artifact_id uuid,version bigint,work_item_erasure_job_id uuid,content_hash bytea,content_id uuid);
CREATE TABLE agent.device_resource_publications(publication_invocation_id uuid,producer_invocation_id uuid,role text,artifact_version_id uuid);
CREATE TABLE resource.device_commands(invocation_id uuid,tenant_id uuid,owner_id uuid,agent_id uuid,run_id uuid,intent_id uuid);
CREATE TABLE agent.dialogue_content_references(tenant_id uuid,owner_id uuid,agent_id uuid,reference_kind text,reference_id uuid,content_id uuid);
CREATE TABLE artifact.content_refs(content_id uuid,tenant_id uuid,state smallint,content_hash bytea);
CREATE TABLE resource.nodes(tenant_id uuid,file_artifact_id uuid,scope_kind smallint,scope_id uuid,kind smallint,lifecycle smallint,name text,name_erasure_job_id uuid);
-- Ownership-function internals are exercised in canonical_resources; this
-- query-boundary fixture retains the artifact/tenant qualification.
CREATE FUNCTION resource.agent_artifact_owned(t uuid,g uuid,a uuid) RETURNS boolean LANGUAGE sql AS $$SELECT EXISTS(SELECT 1 FROM artifact.artifacts WHERE tenant_id=t AND artifact_id=a)$$;
CREATE FUNCTION artifact.device_version_owned(t uuid,o uuid,g uuid,a uuid,v uuid) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
