INSERT INTO agent.dialogue_publications SELECT entry_id,tenant_id,owner_id,dialogue_id,author_agent_id,'device','tool_owner','00000000-0000-0000-0000-000000000006','00000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000008','00000000-0000-0000-0000-000000000009','work_item' FROM agent.agent_dialogue_entries;
INSERT INTO collaboration.work_item_device_admitted_custody VALUES('00000000-0000-0000-0000-00000000000c',1,1,1,'00000000-0000-0000-0000-000000000008','00000000-0000-0000-0000-000000000007',decode('01','hex'),decode('02','hex'),1);
INSERT INTO collaboration.work_item_execution_reservations SELECT d.work_item_id,d.goal_revision,d.control_revision,d.assignment_epoch,d.run_id,d.conversation_id,p.tenant_id,p.owner_id,p.agent_id FROM collaboration.work_item_device_admitted_custody d CROSS JOIN agent.dialogue_publications p;
INSERT INTO collaboration.work_items SELECT r.work_item_id,r.tenant_id,r.owner_id,p.source_intent_id,NULL FROM collaboration.work_item_execution_reservations r CROSS JOIN agent.dialogue_publications p;
INSERT INTO agent.dialogue_tool_publication_groups SELECT source_tool_invocation_id,tenant_id,source_intent_id,source_run_id,'device',decode('01','hex'),decode('02','hex'),'work_item',NULL,decode('04','hex'),'artifacts.deliver@2','00000000-0000-0000-0000-00000000000e' FROM agent.dialogue_publications;
INSERT INTO agent.owned_agents SELECT agent_id,dialogue_id,'00000000-0000-0000-0000-00000000000d','active' FROM agent.dialogue_publications;
INSERT INTO agent.owner_spaces SELECT '00000000-0000-0000-0000-00000000000d',tenant_id,owner_id,'musteragent' FROM agent.dialogue_publications;
INSERT INTO artifact.artifacts SELECT artifact_id,tenant_id,'00000000-0000-0000-0000-000000000007',NULL,NULL,'00000000-0000-0000-0000-000000000008',1,6,1,1,'test.txt',NULL,1,1 FROM agent.agent_dialogue_entries;
INSERT INTO artifact.artifact_versions SELECT artifact_version_id,artifact_id,1,NULL,decode('05','hex'),'00000000-0000-0000-0000-00000000000f' FROM agent.agent_dialogue_entries;
INSERT INTO agent.device_resource_publications SELECT p.source_tool_invocation_id,'00000000-0000-0000-0000-000000000010','delivery',e.artifact_version_id FROM agent.dialogue_publications p CROSS JOIN agent.agent_dialogue_entries e;
INSERT INTO resource.device_commands SELECT '00000000-0000-0000-0000-000000000010',tenant_id,owner_id,agent_id,source_run_id,source_intent_id FROM agent.dialogue_publications;
INSERT INTO resource.nodes SELECT tenant_id,artifact_id,4,author_agent_id,2,1,'test.txt',NULL FROM agent.agent_dialogue_entries;
